(4438240, 638083, 87538, '<td valign="top">the tilt from left to right did not feel good. It also appears that you have some sensor dust which is showing in the sky along the right side.</td>', 'the tilt from left to right did not feel good. It also appears that you have some sensor dust which is showing in the sky along the right side.', '2008-01-30 00:37:10.000000', NULL, 1),
(4438243, 640071, 19245, '<td valign="top">nice sky.</td>', 'nice sky.', '2008-01-30 00:38:48.000000', NULL, 1),
