(4441016, 638766, 50804, '<td valign="top">The vignetting on this is a little distracting and the sky seems like it should be much bluer since it is pretty clear.  Nice framing of the monument, though.</td>', 'The vignetting on this is a little distracting and the sky seems like it should be much bluer since it is pretty clear.  Nice framing of the monument, though.', '2008-01-30 17:24:25.000000', NULL, 1),
(4441020, 639668, 75958, '<td valign="top">Wow what a cool subject I''m interested in were this is. I really like the cropping,and the subject is great, also love the sky. great job</td>', 'Wow what a cool subject I''m interested in were this is. I really like the cropping,and the subject is great, also love the sky. great job', '2008-01-30 17:24:51.000000', NULL, 1),
