(4441026, 639358, 75958, '<td valign="top">good use of perspective and interesting subject matter.</td>', 'good use of perspective and interesting subject matter.', '2008-01-30 17:25:58.000000', NULL, 1),
(4441029, 639343, 86447, '<td valign="top">I wish it were either centered, or more off center to appear intentional.</td>', 'I wish it were either centered, or more off center to appear intentional.', '2008-01-30 17:26:40.000000', NULL, 1),
(4441035, 639372, 50804, '<td valign="top">Interesting building ... it makes the perspective tilt on the left side seem like part of the design.  Seems a little soft, but good exposure.</td>', 'Interesting building ... it makes the perspective tilt on the left side seem like part of the design.  Seems a little soft, but good exposure.', '2008-01-30 17:27:48.000000', NULL, 1),
(4441037, 637875, 75958, '<td valign="top">I like what you were going for in this picture the colors and the smoothness of the building really complement each other.maybe crop it a bit more on the right to get it a bit more symmetrical</td>', 'I like what you were going for in this picture the colors and the smoothness of the building really complement each other.maybe crop it a bit more on the right to get it a bit more symmetrical', '2008-01-30 17:28:13.000000', NULL, 1),
(4441039, 637413, 86447, '<td valign="top">A half of a step to your right as you photographed would make this on center and symmetrical.  If it''s not to be on center then, in my opinion, it need to be MORE off center to appear intentional.   The DOF, sharpness, and color are wonderful.</td>', 'A half of a step to your right as you photographed would make this on center and symmetrical.  If it''s not to be on center then, in my opinion, it need to be MORE off center to appear intentional.   The DOF, sharpness, and color are wonderful.', '2008-01-30 17:29:02.000000', NULL, 1),
(4441041, 639090, 50804, '<td valign="top">The shadow areas (building faces and plaza) seem too light (and thus noisy), unless the painterly quality is what you were going for...</td>', 'The shadow areas (building faces and plaza) seem too light (and thus noisy), unless the painterly quality is what you were going for...', '2008-01-30 17:29:53.000000', NULL, 1),
(4441042, 639959, 75958, '<td valign="top">the angle is  a nice touch are they actually at an angle or is that just how you shot it?</td>', 'the angle is  a nice touch are they actually at an angle or is that just how you shot it?', '2008-01-30 17:29:55.000000', NULL, 1),
(4441043, 639649, 86447, '<td valign="top">This is very well composed, but not sharply focused enough to be a winner, in my opinion.  The blues could be upped a bit, also, to make it more appealing.</td>', 'This is very well composed, but not sharply focused enough to be a winner, in my opinion.  The blues could be upped a bit, also, to make it more appealing.', '2008-01-30 17:30:32.000000', NULL, 1),
