(4441045, 639498, 75958, '<td valign="top">good use of black and white. great image.</td>', 'good use of black and white. great image.', '2008-01-30 17:30:53.000000', NULL, 1),
(4441048, 639504, 80912, '<td valign="top">Sorry but this looks like you didn''t even try to focus.</td>', 'Sorry but this looks like you didn''t even try to focus.', '2008-01-30 17:31:59.000000', NULL, 1),
(4441050, 639558, 75958, '<td valign="top">interesting angle, I don''t know if I like the composition though.</td>', 'interesting angle, I don''t know if I like the composition though.', '2008-01-30 17:32:10.000000', NULL, 1),
(4441052, 639504, 75958, '<td valign="top">nice, very surreal!</td>', 'nice, very surreal!', '2008-01-30 17:32:44.000000', NULL, 1),
(4441054, 639471, 86447, '<td valign="top">This is really wonderfully sharp and a great composition, however...<br/> <br/>A simple step to the right, while photographing (or a tad crop off the left) would have centered this perfectly.  Instead, it has a slightly off-balance feel to me.  In my opinion, it needs to either be dead center or so far off center to appear that it''s intentional.  7</td>', 'This is really wonderfully sharp and a great composition, however... A simple step to the right, while photographing (or a tad crop off the left) would have centered this perfectly.  Instead, it has a slightly off-balance feel to me.  In my opinion, it needs to either be dead center or so far off center to appear that it''s intentional.  7', '2008-01-30 17:32:46.000000', NULL, 1),
(4441055, 639801, 50804, '<td valign="top">Really cool!  Great composition.</td>', 'Really cool!  Great composition.', '2008-01-30 17:32:56.000000', NULL, 1),
(4441059, 639130, 86447, '<td valign="top">It doesn''t appear sharply focused enough to me...   But the lines are interesting.</td>', 'It doesn''t appear sharply focused enough to me...   But the lines are interesting.', '2008-01-30 17:33:39.000000', NULL, 1),
(4441060, 639607, 88148, '<td valign="top">In the short time I''ve been browsing this site, I have seen this so many times it hurts me.</td>', 'In the short time I''ve been browsing this site, I have seen this so many times it hurts me.', '2008-01-30 17:33:59.000000', NULL, 1),
(4441064, 639411, 75958, '<td valign="top">almost feels like your falling into the image. I don''t know if I like the duo tone tho. I know you can''t do this in basic but a vignette on this would work well in my opinion.</td>', 'almost feels like your falling into the image. I don''t know if I like the duo tone tho. I know you can''t do this in basic but a vignette on this would work well in my opinion.', '2008-01-30 17:35:53.000000', NULL, 1),
