(4443612, 638880, 50804, '<td valign="top">Good composition.</td>', 'Good composition.', '2008-01-31 13:41:23.000000', NULL, 1),
(4443617, 639363, 50804, '<td valign="top">Neat old barn.  I would like to see the colors popping more ... the lighting seems a little flat.</td>', 'Neat old barn.  I would like to see the colors popping more ... the lighting seems a little flat.', '2008-01-31 13:44:05.000000', NULL, 1),
(4443618, 639935, 50804, '<td valign="top">Nice mood ... interesting structure.</td>', 'Nice mood ... interesting structure.', '2008-01-31 13:45:09.000000', NULL, 1),
(4443624, 639359, 50804, '<td valign="top">For me, this would have worked better either perfectly centered or else taken from the corner.  The shadow area at the bottom is distracting from the otherwise nice lighting.</td>', 'For me, this would have worked better either perfectly centered or else taken from the corner.  The shadow area at the bottom is distracting from the otherwise nice lighting.', '2008-01-31 13:47:14.000000', NULL, 1),
(4443626, 639891, 50804, '<td valign="top">Neat elevators but I think there are too many lines and shapes going on for me.</td>', 'Neat elevators but I think there are too many lines and shapes going on for me.', '2008-01-31 13:48:21.000000', NULL, 1),
(4443633, 638136, 50804, '<td valign="top">Tough lighting situation ... you seemed to have pulled it off as well as could be hoped!</td>', 'Tough lighting situation ... you seemed to have pulled it off as well as could be hoped!', '2008-01-31 13:50:35.000000', NULL, 1),
(4443638, 639851, 50804, '<td valign="top">The uneven side lighting is a little distracting ... feels like too much is lost in the shadows.  Good perspective otherwise.</td>', 'The uneven side lighting is a little distracting ... feels like too much is lost in the shadows.  Good perspective otherwise.', '2008-01-31 13:53:17.000000', NULL, 1),
