(4443644, 639893, 50804, '<td valign="top">The flash lighting made things a little harsh, yet the window lighting looks blurred.</td>', 'The flash lighting made things a little harsh, yet the window lighting looks blurred.', '2008-01-31 13:55:30.000000', NULL, 1),
(4443645, 638859, 47541, '<td valign="top">Houston? When I called in to see <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=52713" rel="nofollow" target="_blank">scarbrd</a> he showed me a funky building that had a slanted glass roof that seemed like this.  I''d know for sure if you were standing a few metres to the left!</td>', 'Houston? When I called in to see  scarbrd he showed me a funky building that had a slanted glass roof that seemed like this.  I''d know for sure if you were standing a few metres to the left!', '2008-01-31 13:56:26.000000', NULL, 1),
(4443650, 639441, 47541, '<td valign="top">This is a POV I''ve not seen before.  I''ll come back after voting to find out where you were when you took this shot</td>', 'This is a POV I''ve not seen before.  I''ll come back after voting to find out where you were when you took this shot', '2008-01-31 13:59:22.000000', NULL, 1),
(4443651, 639705, 50804, '<td valign="top">Seems too heavily weighted to the right side ... the structures here don''t seem very fisheye-friendly, and the person (whether you wanted him there or not) is trivialized by the lens and lost in the shadows, so he doesn''t add anything.</td>', 'Seems too heavily weighted to the right side ... the structures here don''t seem very fisheye-friendly, and the person (whether you wanted him there or not) is trivialized by the lens and lost in the shadows, so he doesn''t add anything.', '2008-01-31 13:59:34.000000', NULL, 1),
(4443654, 638676, 50804, '<td valign="top">Neat lighting -- good job keeping the detail in both shadows and highlights.</td>', 'Neat lighting -- good job keeping the detail in both shadows and highlights.', '2008-01-31 14:00:08.000000', NULL, 1),
(4443657, 639262, 50804, '<td valign="top">Interesting building ... and I can''t tell whether that is sky or fog in front of tall mountains behind.  The picture appears very noisy, which is obscuring fine details.</td>', 'Interesting building ... and I can''t tell whether that is sky or fog in front of tall mountains behind.  The picture appears very noisy, which is obscuring fine details.', '2008-01-31 14:02:27.000000', NULL, 1),
(4443659, 639358, 50804, '<td valign="top">This is neat ... too bad the steel netting has to be there.  At first I wanted to see the top in focus, but then your title helped explain the focus.</td>', 'This is neat ... too bad the steel netting has to be there.  At first I wanted to see the top in focus, but then your title helped explain the focus.', '2008-01-31 14:03:48.000000', NULL, 1),
(4443662, 640011, 50804, '<td valign="top">Nicely done B&amp;W.</td>', 'Nicely done B&W.', '2008-01-31 14:06:37.000000', NULL, 1),
(4443663, 639556, 50804, '<td valign="top">I feel like there is too much sky here (even though it has an interesting texture) ... it and the tree draw my eye away from the building.  Would have preferred a close-in shot of some of the more interesting architectural detail.</td>', 'I feel like there is too much sky here (even though it has an interesting texture) ... it and the tree draw my eye away from the building.  Would have preferred a close-in shot of some of the more interesting architectural detail.', '2008-01-31 14:09:37.000000', NULL, 1),
(4443684, 639287, 50804, '<td valign="top">Slight lean to the left and slightly overexposed.  One step to your left would have closed up the distracting gap into the courtyard.  Neat walkway though!</td>', 'Slight lean to the left and slightly overexposed.  One step to your left would have closed up the distracting gap into the courtyard.  Neat walkway though!', '2008-01-31 14:21:34.000000', NULL, 1),
(4443685, 639914, 50804, '<td valign="top">Funky buildings.  That sky is gorgeous!</td>', 'Funky buildings.  That sky is gorgeous!', '2008-01-31 14:22:16.000000', NULL, 1),
(4443690, 638699, 35044, '<td valign="top">Is this Bilbao?  My favourite - great colours and nice capture of light patterns.</td>', 'Is this Bilbao?  My favourite - great colours and nice capture of light patterns.', '2008-01-31 14:25:16.000000', NULL, 1),
(4443692, 639317, 35044, '<td valign="top">Great lines and colour make this stand out.</td>', 'Great lines and colour make this stand out.', '2008-01-31 14:25:34.000000', NULL, 1),
