(4443725, 640063, 35044, '<td valign="top">nice simplicity about this</td>', 'nice simplicity about this', '2008-01-31 14:35:58.000000', NULL, 1),
(4443727, 637251, 35044, '<td valign="top">soft focus effect will not be liked by all, but I really like it here - I would be interested to know your sharpening settings as there is something almost ethereal about this.</td>', 'soft focus effect will not be liked by all, but I really like it here - I would be interested to know your sharpening settings as there is something almost ethereal about this.', '2008-01-31 14:36:52.000000', NULL, 1),
