INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4445505, 638602, 86799, '<td valign="top">Excellent.  The steam pipe flourish is right on.</td>', 'Excellent.  The steam pipe flourish is right on.', '2008-02-01 05:05:37.000000', NULL, 1),
(4445753, 639649, 88492, '<td valign="top">out of focus.<br/>not enough architecture</td>', 'out of focus.not enough architecture', '2008-02-01 08:24:25.000000', NULL, 1),
(4445754, 637816, 56002, '<td valign="top">What a handsome structure this is.  And a fine job capturing it.  Love the dim yellow fading back into gray (grey).  Something here, whether it is the structure''s form or the photographer''s composition says strong and proud.</td>', 'What a handsome structure this is.  And a fine job capturing it.  Love the dim yellow fading back into gray (grey).  Something here, whether it is the structure''s form or the photographer''s composition says strong and proud.', '2008-02-01 08:24:46.000000', NULL, 1),
(4445772, 639504, 88492, '<td valign="top">too out of focus<br/>can''t see the architecture at all</td>', 'too out of focuscan''t see the architecture at all', '2008-02-01 08:32:28.000000', NULL, 1),
(4445784, 639596, 88492, '<td valign="top">Looks like something out of blade runner.</td>', 'Looks like something out of blade runner.', '2008-02-01 08:38:32.000000', NULL, 1),
(4445796, 639575, 88492, '<td valign="top">I feel that there is too much bridge and not enough of the colourful first arch.<br/>I think just 3 or 4 arches would have looked better.</td>', 'I feel that there is too much bridge and not enough of the colourful first arch.I think just 3 or 4 arches would have looked better.', '2008-02-01 08:42:03.000000', NULL, 1),
(4445923, 639897, 19670, '<td valign="top">I''ve been wanting to see "So I Married an Axe Murderer" recently...<br/>Good composition, probably could have been better with less direct sunlight.</td>', 'I''ve been wanting to see "So I Married an Axe Murderer" recently...Good composition, probably could have been better with less direct sunlight.', '2008-02-01 09:31:50.000000', NULL, 1),
(4445931, 639616, 19670, '<td valign="top">I suggest shooting from farther away and zooming in to have more parallel lines.</td>', 'I suggest shooting from farther away and zooming in to have more parallel lines.', '2008-02-01 09:33:20.000000', NULL, 1),
(4445933, 638870, 19670, '<td valign="top">Dramatic look</td>', 'Dramatic look', '2008-02-01 09:33:37.000000', NULL, 1),
(4445934, 639317, 19670, '<td valign="top">Nice smooth tones.</td>', 'Nice smooth tones.', '2008-02-01 09:33:53.000000', NULL, 1),
