(4446022, 637530, 19670, '<td valign="top">Overexposed sky on left, and some of the stalks on the ground, too.</td>', 'Overexposed sky on left, and some of the stalks on the ground, too.', '2008-02-01 09:48:35.000000', NULL, 1),
(4446028, 639656, 19670, '<td valign="top">Interested selective-desaturation look.</td>', 'Interested selective-desaturation look.', '2008-02-01 09:49:21.000000', NULL, 1),
