(4453713, 639130, 43774, '<td valign="top">I love the look of those branches. I wish the building were in focus. This is a good compositon, a photo of contrasts.</td>', 'I love the look of those branches. I wish the building were in focus. This is a good compositon, a photo of contrasts.', '2008-02-03 13:18:35.000000', NULL, 1),
(4453715, 639818, 76185, '<td valign="top">Nice converging lines, perhaps a little too much foreground?</td>', 'Nice converging lines, perhaps a little too much foreground?', '2008-02-03 13:18:47.000000', NULL, 1),
(4453719, 638753, 43774, '<td valign="top">The Capitol Building is such a grand building. I am not liking your processing here though, the orange sky and black water are just too unnatural looking.</td>', 'The Capitol Building is such a grand building. I am not liking your processing here though, the orange sky and black water are just too unnatural looking.', '2008-02-03 13:19:18.000000', NULL, 1),
(4453722, 638221, 43774, '<td valign="top">Nice silhouette but I don''t see this as an architecture shot. Did you use a filter? The view through the window looks like a painting.</td>', 'Nice silhouette but I don''t see this as an architecture shot. Did you use a filter? The view through the window looks like a painting.', '2008-02-03 13:20:04.000000', NULL, 1),
(4453723, 639596, 76185, '<td valign="top">Nice modern/urban subject matter. Can imagine some potential for good abstract angles and close ups here too.</td>', 'Nice modern/urban subject matter. Can imagine some potential for good abstract angles and close ups here too.', '2008-02-03 13:20:06.000000', NULL, 1),
(4453727, 639881, 43774, '<td valign="top">Nice leading lines, good perspective. The overexposure bothers me a bit.</td>', 'Nice leading lines, good perspective. The overexposure bothers me a bit.', '2008-02-03 13:20:29.000000', NULL, 1),
(4453729, 639562, 76185, '<td valign="top">Nice effect, although a bit too much lean imo.</td>', 'Nice effect, although a bit too much lean imo.', '2008-02-03 13:20:44.000000', NULL, 1),
(4453731, 639860, 43774, '<td valign="top">A nice view, framed well but not quite in focus. You should also set your camera so the date is not displayed on the photo.</td>', 'A nice view, framed well but not quite in focus. You should also set your camera so the date is not displayed on the photo.', '2008-02-03 13:21:13.000000', NULL, 1),
(4453734, 639607, 76185, '<td valign="top">Curves used well to draw you through the image, nice warm colour.</td>', 'Curves used well to draw you through the image, nice warm colour.', '2008-02-03 13:21:28.000000', NULL, 1),
