INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4457064, 639832, 89452, '<td valign="top">I like the reflection</td>', 'I like the reflection', '2008-02-04 11:36:01.000000', NULL, 1),
(4457071, 639588, 89452, '<td valign="top">Haunting</td>', 'Haunting', '2008-02-04 11:40:05.000000', NULL, 1),
(4457077, 638337, 89452, '<td valign="top">To much parking lot.</td>', 'To much parking lot.', '2008-02-04 11:41:47.000000', NULL, 1),
(4457212, 637530, 88729, '<td valign="top">The foreground looks good, but the coloring of the barn and the sky seems a little off.</td>', 'The foreground looks good, but the coloring of the barn and the sky seems a little off.', '2008-02-04 12:41:38.000000', NULL, 1),
(4457218, 638443, 88729, '<td valign="top">it almost looks like the building is smiling</td>', 'it almost looks like the building is smiling', '2008-02-04 12:43:33.000000', NULL, 1),
(4457222, 637843, 88729, '<td valign="top">i like the shape and contrast of color</td>', 'i like the shape and contrast of color', '2008-02-04 12:45:20.000000', NULL, 1),
(4457226, 638089, 88729, '<td valign="top">sky looks great</td>', 'sky looks great', '2008-02-04 12:47:09.000000', NULL, 1),
(4457282, 639649, 56539, '<td valign="top">Very  blurred</td>', 'Very  blurred', '2008-02-04 13:06:46.000000', NULL, 1),
(4457465, 639818, 57777, '<td valign="top">great work! I like the angle, and it has strong textures. After the challenge, I would definatley do some burning to the sky to ad even more texture!</td>', 'great work! I like the angle, and it has strong textures. After the challenge, I would definatley do some burning to the sky to ad even more texture!', '2008-02-04 14:00:33.000000', NULL, 1),
(4457466, 638554, 57777, '<td valign="top">I think a longer exposure to throw the people out of focus would have helped as they are very distracting, but the lines and colors are beautiful</td>', 'I think a longer exposure to throw the people out of focus would have helped as they are very distracting, but the lines and colors are beautiful', '2008-02-04 14:00:37.000000', NULL, 1),
(4457472, 638689, 57777, '<td valign="top">Very nice sky, and good color. Nice exposure as well. Its a fine subject, but I feel that this was approached in such a stereotypical angle. It would have worked better if you would have shot different angles, shot just the reflections in the windows, or something</td>', 'Very nice sky, and good color. Nice exposure as well. Its a fine subject, but I feel that this was approached in such a stereotypical angle. It would have worked better if you would have shot different angles, shot just the reflections in the windows, or something', '2008-02-04 14:03:58.000000', NULL, 1),
(4457475, 638676, 57777, '<td valign="top">Very pretty picture and very nice toning. I think that certain areas of this photo are just a little to dark. Great work though!</td>', 'Very pretty picture and very nice toning. I think that certain areas of this photo are just a little to dark. Great work though!', '2008-02-04 14:05:30.000000', NULL, 1),
(4457478, 638126, 57777, '<td valign="top">While this is not the most intersting subject in the world, you did a great job with the approach and idea on this. Good, clear reflection, nice color and good exposure. Feels very technically sound.</td>', 'While this is not the most intersting subject in the world, you did a great job with the approach and idea on this. Good, clear reflection, nice color and good exposure. Feels very technically sound.', '2008-02-04 14:06:28.000000', NULL, 1),
(4457481, 638065, 57777, '<td valign="top">great pattern here. Feels like it may be a bit soft, but that could just be the quality of the upload. Its a good tight crop, which is nice in this challenge, where so many others are pulled back so far. My only problem with this photo is the colors really are so dull, flat and unexciting.</td>', 'great pattern here. Feels like it may be a bit soft, but that could just be the quality of the upload. Its a good tight crop, which is nice in this challenge, where so many others are pulled back so far. My only problem with this photo is the colors really are so dull, flat and unexciting.', '2008-02-04 14:08:04.000000', NULL, 1),
(4457485, 638221, 57777, '<td valign="top">Seems more about the statue than the architecture. I guess there is a difference in my mind. under exposed in some areas, and to exposed, and oversaturated in the background. Good idea for a picture, but needs some work technically. Would also try other angles than "straight on" with it as well</td>', 'Seems more about the statue than the architecture. I guess there is a difference in my mind. under exposed in some areas, and to exposed, and oversaturated in the background. Good idea for a picture, but needs some work technically. Would also try other angles than "straight on" with it as well', '2008-02-04 14:10:00.000000', NULL, 1),
