(4461914, 639935, 60495, '<td valign="top">Cool building, nicely done.</td>', 'Cool building, nicely done.', '2008-02-06 00:08:04.000000', NULL, 0),
(4461916, 639962, 85886, '<td valign="top">Nice placing MAK - this was my other 9 given, tied with Matthew''s blue.  I think you should have finished in a ribbon slot personally but hey, what do I know :)</td>', 'Nice placing MAK - this was my other 9 given, tied with Matthew''s blue.  I think you should have finished in a ribbon slot personally but hey, what do I know :)', '2008-02-06 00:08:22.000000', NULL, 0),
