INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4896102, 638870, 28742, '<td valign="top">HA! I WISH!! :)</td>', 'HA! I WISH!! :)', '2008-08-18 19:52:36.000000', NULL, 0),
(4899064, 639801, 59267, '<td valign="top">Awesome shot! did you shot this for National Geographic?</td>', 'Awesome shot! did you shot this for National Geographic?', '2008-08-20 02:00:06.000000', NULL, 0),
(4901117, 639891, 59267, '<td valign="top">Wow! nice shot!! beautiful place and you chose an excellent perspective view.</td>', 'Wow! nice shot!! beautiful place and you chose an excellent perspective view.', '2008-08-20 19:59:58.000000', NULL, 0),
(4922391, 637413, 69008, '<td valign="top">Lines, form and color combine to make this place impressive. You''ve made a fine image here from start to finish. The difference in the foreground in the lower part adds quite a lot to the overall composition with the straight line from one side, and the angle line on the right. <br/>There is a civil war fort out in the Gulf of Mexico that looks a lot like this inside the walls. It''s one of my favorite places to visit.</td>', 'Lines, form and color combine to make this place impressive. You''ve made a fine image here from start to finish. The difference in the foreground in the lower part adds quite a lot to the overall composition with the straight line from one side, and the angle line on the right. There is a civil war fort out in the Gulf of Mexico that looks a lot like this inside the walls. It''s one of my favorite places to visit.', '2008-08-31 00:06:47.000000', NULL, 0),
(4950987, 637831, 30982, '<td valign="top">VERY clever with the slow speed, low ISO to make the people disappear.  I was wondering how you got this with no people!!</td>', 'VERY clever with the slow speed, low ISO to make the people disappear.  I was wondering how you got this with no people!!', '2008-09-11 20:30:07.000000', NULL, 0),
